REFERENCE cxx_stoi (byte-exact against the binary on 53 probes):

fn c_isspace(b: u8) -> bool { matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') }

fn cxx_stoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    while i < bytes.len() && c_isspace(bytes[i]) { i += 1; }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') { neg = bytes[i] == b'-'; i += 1; }
    let dstart = i;
    let mut acc: i128 = 0;
    let mut sat = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        if !sat { acc = acc * 10 + (bytes[i] - b'0') as i128; if acc > 4_000_000_000_000_000_000_000i128 { sat = true; } }
        i += 1;
    }
    if i == dstart { cxx_terminate("std::invalid_argument", "stoi"); }   // endptr == str
    if sat { cxx_terminate("std::out_of_range", "stoi"); }
    let v: i128 = if neg { -acc } else { acc };
    if v < i32::MIN as i128 || v > i32::MAX as i128 { cxx_terminate("std::out_of_range", "stoi"); }
    v as i32
}
